import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage() });

interface MatchResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

router.post('/api/scan-resume', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume PDF file uploaded.' });
      return;
    }

    const jobDescription = req.body.jobDescription as string;
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required.' });
      return;
    }

    // Parse PDF buffer
    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();

    // Simple keyword extraction & matching logic
    const rawKeywords = jobDescription
      .toLowerCase()
      .replace(/[^\w\s]/gi, '')
      .split(/\s+/);

    // Filter out common stop words
    const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'with', 'an']);
    const uniqueKeywords = Array.from(new Set(rawKeywords)).filter(kw => kw.length > 2 && !stopWords.has(kw));

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    uniqueKeywords.forEach(keyword => {
      if (resumeText.includes(keyword)) {
        matchedKeywords.push(keyword);
      } else {
        missingKeywords.push(keyword);
      }
    });

    const matchScore = uniqueKeywords.length > 0 
      ? Math.round((matchedKeywords.length / uniqueKeywords.length) * 100) 
      : 0;

    const result: MatchResult = {
      matchScore,
      matchedKeywords,
      missingKeywords,
      totalKeywordsChecked: uniqueKeywords.length,
    };

    res.json(result);
  } catch (error) {
    console.error('Error processing resume:', error);
    res.status(500).json({ error: 'Internal server error while parsing PDF.' });
  }
});

export default router;

import React, { useEffect, useState } from 'react';

interface AnimatedMatchScoreGaugeProps {
  score: number;
}

export const AnimatedMatchScoreGauge: React.FC<AnimatedMatchScoreGaugeProps> = ({ score }) => {
  const [animatedScore, setAnimatedScore] = useState(0);

  useEffect(() => {
    const timer = setTimeout(() => {
      setAnimatedScore(score);
    }, 100);
    return () => clearTimeout(timer);
  }, [score]);

  const radius = 54;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (animatedScore / 100) * circumference;

  const getColor = (s: number) => {
    if (s >= 80) return 'text-emerald-500 stroke-emerald-500';
    if (s >= 50) return 'text-amber-500 stroke-amber-500';
    return 'text-rose-500 stroke-rose-500';
  };

  return (
    <div className="flex flex-col items-center justify-center p-6 bg-white rounded-2xl shadow-lg border border-slate-100">
      <div className="relative flex items-center justify-center">
        <svg className="w-36 h-36 transform -rotate-90">
          <circle
            cx="72"
            cy="72"
            r={radius}
            stroke="currentColor"
            strokeWidth="12"
            className="text-slate-100"
            fill="transparent"
          />
          <circle
            cx="72"
            cy="72"
            r={radius}
            strokeWidth="12"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            fill="transparent"
            className={`transition-all duration-1000 ease-out ${getColor(animatedScore)}`}
          />
        </svg>
        <div className="absolute flex flex-col items-center">
          <span className="text-3xl font-extrabold text-slate-800">{animatedScore}%</span>
          <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Match Score</span>
        </div>
      </div>
    </div>
  );
};
